import sys

def main():
    data = sys.stdin.read().split()
    if len(data) < 2:
        return
    my_hand, opp_hand = data[0], data[1]
    mapping = {"グー":0,"チョキ":1,"パー":2}
    result_map = {0:"あいこ",1:"負け",2:"勝ち"}
    my = mapping.get(my_hand)
    opp = mapping.get(opp_hand)
    if my is None or opp is None:
        # maybe invalid input; but not required.
        return
    if my == opp:
        res = 0
    elif (my, opp) in [(0,1),(1,2),(2,0)]:
        res = 2   # win
    else:
        res = 1   # lose
    print(result_map[res])

if __name__ == "__main__":
    main()

